package main
import("encoding/json";"flag";"fmt";"os";"os/exec";"time")
type Cmd struct{Name string `json:"name"`;Image string `json:"image"`;Args []string `json:"args"`;PID int `json:"pid,omitempty"`;ExitCode int `json:"exit_code"`;Output string `json:"output,omitempty"`;OK bool `json:"ok"`;Error string `json:"error,omitempty"`}
type Ledger struct{Fixture string `json:"fixture"`;Mode string `json:"mode"`;PID int `json:"pid"`;PPID int `json:"ppid"`;Started string `json:"started"`;Ended string `json:"ended"`;Commands []Cmd `json:"commands"`}
func main(){neg := flag.Bool("negative", true, "negative control: do not launch cmd.exe or PowerShell");flag.Parse();s:=time.Now().UTC();mode:="positive";if *neg{mode="negative-control"};l:=Ledger{Fixture:"mitre-shells",Mode:mode,PID:os.Getpid(),PPID:os.Getppid(),Started:s.Format(time.RFC3339Nano)};if !*neg{l.Commands=append(l.Commands,run("Windows Command Shell","cmd.exe",[]string{"/d","/c","ver"}));l.Commands=append(l.Commands,run("PowerShell","powershell.exe",[]string{"-NoProfile","-NonInteractive","-Command","Write-Output 'ThreatBox benign detection test'"}))}else{fmt.Println("Negative control: no cmd.exe or PowerShell child process will be launched.")};l.Ended=time.Now().UTC().Format(time.RFC3339Nano);b,e:=json.Marshal(l);if e!=nil{fmt.Printf("GROUND_TRUTH error=%q\n",e);os.Exit(2)};fmt.Printf("GROUND_TRUTH %s\n",b);for _,c:=range l.Commands{if !c.OK{os.Exit(3)}}}
func run(name,image string,args []string)Cmd{s:=time.Now();cmd:=exec.Command(image,args...);out,e:=cmd.CombinedOutput();r:=Cmd{Name:name,Image:image,Args:args,Output:string(out),OK:e==nil};if cmd.Process!=nil{r.PID=cmd.Process.Pid};if cmd.ProcessState!=nil{r.ExitCode=cmd.ProcessState.ExitCode()};if e!=nil{r.Error=e.Error()};fmt.Printf("COMMAND_RESULT name=%q image=%q pid=%d exit=%d elapsed_ms=%d ok=%t\n",name,image,r.PID,r.ExitCode,time.Since(s).Milliseconds(),r.OK);return r}
